sys_variable_value.value:
(function execute(inputs, outputs) {
    outputs.run_start = null;
    var gr = new GlideRecord(inputs.table);
    if(gr.get(inputs.sysid)){
         outputs.run_start = gr.getValue("run_start");
    }
})(inputs, outputs);

